head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > P > calendarImageOver]<br/>컴포넌트의 버튼 영역에 마우스 오버 시 적용할 이미지를 URL 로 설정합니다.",
    "validation" : [
        "버튼 영역에 마우스 오버 시 적용할 이미지의 URL 을 설정합니다.",
        "상대경로를 설정할 수 있어야 합니다.",        
        "절대경로를 설정할 수 있어야 합니다.",        
        "프로토콜 포함 경로를 설정할 수 있어야 합니다.",        
        "PNG, JPG, JPEG, GIF, SVG 등 브라우저가 지원하는 모든 이미지 파일을 사용할 수 있어야 합니다.",
        "renderDiv=true 이면 버튼 영역으로 렌더링 되는 button 태그의 style 속성에 background-image 로 적용됩니다.",
        "renderDiv=false 이면 버튼 영역으로 렌더링 되는 img 태그의 src 속성에 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        calendarImage : "/websquare/_websquare_/uiplugin/inputCalendar/images/icon_calendar_over.gif",
        calendarImageOver : con_calendarImageOver.getText(),
        renderDiv : con_renderDiv.getText(),       
    }

    let cList = $c.gcm.createCList(properties)
    let eList = $c.gcm.createEList(["onclick"]);

    $c.gcm.createLabel('label="calendarImageOver 설정 후 버튼 영역 클릭하여 확인"', '', 'label1');
    // comp 생성 함수 호출
    $c.gcm.createBasicInputCalendar(cList, eList);
}



scwin.btn_getCalendarImageOver_onclick = function (e) {
    // id가 "target1"을 포함하는 요소를 찾기
    let targetEmement = document.querySelector('[id*="target1"]');

    if (targetEmement) {
        let buttonElement = null;
        let imageElement = null;

        if (target1.options.renderDiv === true) {

            // id가 "target1_img"인 button 태그 찾기
            buttonElement = targetEmement.querySelector('button[id*="target1_img"]');

            wf_body_bottom.getObj("scwin").setReturnValue('button backgroundImage :' + buttonElement.style.backgroundImage);
        }
        else {
            // id가 "target1_img"인 image 태그 찾기
            imageElement = targetEmement.querySelector('img[id*="target1_img"]');  

            let url = imageElement.src;

            // 마지막 두 개의 '/' 위치 찾기
            let lastSlashIndex = url.lastIndexOf('/');
            let secondLastSlashIndex = url.lastIndexOf('/', lastSlashIndex - 1);

            // '/img/gif.gif' 부분 추출
            let folderAndFile = url.substring(secondLastSlashIndex);

            wf_body_bottom.getObj("scwin").setReturnValue('image src : ' + folderAndFile);
        }
    }	
};



scwin.target1_onclick = function (e) {
    scwin.btn_getCalendarImageOver_onclick();
}
